import com.harbor.billing.domain.Invoice
import com.harbor.billing.domain.InvoiceRepository
import com.harbor.billing.domain.Money
import org.springframework.stereotype.Service

/** Application service — orchestrates the aggregate through the port. */
@Service
class BillingService(private val invoiceRepository: InvoiceRepository) {
  fun addLine(invoiceId: Long, amountMinor: Int): Invoice {
    val invoice = invoiceRepository.byId(invoiceId)
      ?: throw NoSuchElementException("invoice $invoiceId not found")
    if (amountMinor <= 0) {
      throw IllegalArgumentException("line amount must be positive")
    }
    invoice.addLine(Money(amountMinor, "EUR"))
    return invoiceRepository.save(invoice)
  }

  fun get(invoiceId: Long): Invoice? {
    return invoiceRepository.byId(invoiceId)
  }

  fun settle(invoiceId: Long): Invoice {
    val invoice = invoiceRepository.byId(invoiceId)
      ?: throw NoSuchElementException("invoice $invoiceId not found")
    invoice.settle()
    return invoiceRepository.save(invoice)
  }
}

package com.harbor.billing.domain

/** The aggregate root: state and the transitions live together. */
class Invoice(val id: Long, val customerId: Long) {
  private val lines = mutableListOf<Money>()
  var status: String = "draft"
    private set

  fun addLine(line: Money) {
    if (status == "settled") {
      throw IllegalStateException("settled invoices are immutable")
    }
    lines.add(line)
  }

  fun total(): Money {
    var sum = Money(0, "EUR")
    for (line in lines) {
      sum = sum + line
    }
    return sum
  }

  fun settle() {
    if (total().amountMinor <= 0) {
      throw IllegalStateException("nothing to settle")
    }
    status = "settled"
  }
}

package com.harbor.billing.domain

/** The port: the domain speaks this, infrastructure satisfies it. */
interface InvoiceRepository {
  fun save(invoice: Invoice): Invoice
  fun byId(id: Long): Invoice?
}

package com.harbor.billing.domain

/** DDD value object — equality is by fields, never by identity. */
data class Money(val amountMinor: Int, val currency: String) {
  operator fun plus(other: Money): Money {
    if (currency != other.currency) {
      throw IllegalArgumentException("currency mismatch $currency vs ${other.currency}")
    }
    return Money(amountMinor + other.amountMinor, currency)
  }
}

